changeSet.sql:
CREATE TABLE estates ( id uuid NOT NULL, tenant_id uuid, branch_id uuid, created_at timestamp(6) with time zone NOT NULL, updated_at timestamp(6) with time zone, created_by varchar(255), updated_by varchar(255), deleted boolean NOT NULL,
name varchar(255) NOT NULL, slug varchar(255) NOT NULL, description text, area varchar(255), city varchar(255), state varchar(64), address varchar(255), footprint geometry(Polygon,4326), corner_premium_pct numeric(5,2), intent varchar(32), published boolean NOT NULL, published_at timestamp(6) with time zone, image_url varchar(255),
PRIMARY KEY (id) );
COMMENT ON COLUMN estates.footprint IS 'Estate boundary, SRID 4326 (WGS84 lat/lng). Compute area with ST_Area(footprint::geography) for square metres — ST_Area on raw 4326 returns square DEGREES, which is not an error, just a plausible-looking wrong number.'; COMMENT ON COLUMN estates.corner_premium_pct IS 'A MODIFIER, never a separate tier: a corner plot costs its tier price x (1 + this/100), computed. Storing a corner price separately would create a second figure that can drift from the tier it derives from.'; COMMENT ON COLUMN estates.published IS 'The developer''s own opt-in switch — ONE of four conditions, not the whole gate. An estate is publicly listable only when ALL of: published = true; the owning tenant verification_state = VERIFIED; that tenant holds the marketplacePublishing entitlement; and tenant status is not SUSPENDED. That check belongs to the marketplace projection, deliberately not to this schema. See AGENTS.md so it is not reinvented or half-implemented there.';
ALTER TABLE estates ADD CONSTRAINT chk_estates_intent CHECK (intent IS NULL OR intent IN ('DEVELOPMENT', 'INVESTMENT', 'BOTH'));

CREATE TABLE estate_amenities ( id uuid NOT NULL, tenant_id uuid, branch_id uuid, created_at timestamp(6) with time zone NOT NULL, updated_at timestamp(6) with time zone, created_by varchar(255), updated_by varchar(255), deleted boolean NOT NULL,
estate_id uuid NOT NULL, name varchar(255) NOT NULL,
PRIMARY KEY (id) );
